package hooks

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
)

// defaultIDPHost is where the generated SDK sends IdP operations
// (service create/remove, audit).
const defaultIDPHost = "login.authlete.com"

// saasAPIServerIDs maps each Authlete SaaS cluster to the apiServerId the IdP
// expects when creating or removing a service on it.
var saasAPIServerIDs = map[string]int64{
	"us.authlete.com": 76281,
	"jp.authlete.com": 53285,
	"eu.authlete.com": 63294,
	"br.authlete.com": 47363,
}

// ErrServiceIDNotSet is returned, before anything is sent, when an operation
// needs a service ID and none was given on the client or the request.
var ErrServiceIDNotSet = errors.New("authlete: serviceId is not set: pass authlete.WithServiceID(...) to New, or set ServiceID on this request")

// IDPRouting is a before-request hook, registered on every client, that lets
// one client serve both the main API and the Authlete IdP:
//
//   - IDPURL, when set, replaces https://login.authlete.com for IdP requests
//     (path prefixes are kept), for DC and self-managed deployments.
//   - APIServerID is added to service create/remove request bodies that do
//     not already carry one. When it is not set and IDPURL is the default,
//     it is derived from the SDK's SaaS server URL.
//
// It also stops requests whose service ID was never set.
type IDPRouting struct {
	IDPURL      string
	APIServerID *int64
}

// IDPRouting returns h's IdP routing hook, registering one on first use.
func (h *Hooks) IDPRouting() *IDPRouting {
	for _, hook := range h.beforeRequestHook {
		if r, ok := hook.(*IDPRouting); ok {
			return r
		}
	}
	r := &IDPRouting{}
	h.registerBeforeRequestHook(r)
	return r
}

func (r *IDPRouting) BeforeRequest(hookCtx BeforeRequestContext, req *http.Request) (*http.Request, error) {
	if strings.Contains(req.URL.Path, "{serviceId}") {
		return req, ErrServiceIDNotSet
	}
	if req.URL.Host != defaultIDPHost {
		return req, nil
	}

	if id := r.apiServerID(hookCtx); id != nil && isServiceCreateOrRemove(req) {
		if err := injectAPIServerID(req, *id); err != nil {
			return req, err
		}
	}

	if r.IDPURL != "" {
		base, err := url.Parse(strings.TrimRight(r.IDPURL, "/"))
		if err != nil || base.Scheme == "" || base.Host == "" {
			return req, fmt.Errorf("authlete: invalid IDP URL %q", r.IDPURL)
		}
		u := *req.URL
		u.Scheme, u.Host = base.Scheme, base.Host
		u.Path = base.Path + req.URL.Path
		u.RawPath = ""
		req.URL = &u
		req.Host = ""
	}
	return req, nil
}

func (r *IDPRouting) apiServerID(hookCtx BeforeRequestContext) *int64 {
	if r.APIServerID != nil {
		return r.APIServerID
	}
	// A custom IdP means a DC or self-managed deployment, where SaaS cluster
	// IDs do not apply. Authlete's own IdP URL counts as the default.
	if r.IDPURL != "" {
		u, err := url.Parse(r.IDPURL)
		if err != nil || u.Host != defaultIDPHost {
			return nil
		}
	}
	serverURL, _ := hookCtx.SDKConfiguration.GetServerDetails()
	u, err := url.Parse(serverURL)
	if err != nil {
		return nil
	}
	if id, ok := saasAPIServerIDs[u.Host]; ok {
		return &id
	}
	return nil
}

func isServiceCreateOrRemove(req *http.Request) bool {
	return req.Method == http.MethodPost &&
		(req.URL.Path == "/api/service" || req.URL.Path == "/api/service/remove")
}

func injectAPIServerID(req *http.Request, id int64) error {
	if req.Body == nil {
		return nil
	}
	raw, err := io.ReadAll(req.Body)
	req.Body.Close()
	if err != nil {
		return err
	}
	var body map[string]any
	if err := json.Unmarshal(raw, &body); err != nil {
		// Not JSON: leave the request as it was.
		setBody(req, raw)
		return nil
	}
	if _, ok := body["apiServerId"]; !ok {
		body["apiServerId"] = id
		if raw, err = json.Marshal(body); err != nil {
			return err
		}
	}
	setBody(req, raw)
	return nil
}

func setBody(req *http.Request, b []byte) {
	req.Body = io.NopCloser(bytes.NewReader(b))
	req.GetBody = func() (io.ReadCloser, error) { return io.NopCloser(bytes.NewReader(b)), nil }
	req.ContentLength = int64(len(b))
}
